@namespace sv_8222d9947e2f4a1e8633d4da37346d27.Components.Pages.Settings

<nav class="nav flex-column nav-pills settings-sidebar" role="tablist">
    @foreach (var section in Sections)
    {
        <button class="nav-link text-start @(section == ActiveSection ? "active" : "")"
                role="tab"
                aria-selected="@(section == ActiveSection)"
                @onclick="() => OnSectionChanged.InvokeAsync(section)">
            <span class="me-2">@GetIcon(section)</span>
            @section
        </button>
    }
</nav>

@code {
    [Parameter, EditorRequired]
    public string ActiveSection { get; set; } = "";

    [Parameter, EditorRequired]
    public EventCallback<string> OnSectionChanged { get; set; }

    private static readonly string[] Sections = ["Profile", "Notifications", "Security", "Appearance"];

    private static string GetIcon(string section) => section switch
    {
        "Profile" => "👤",
        "Notifications" => "🔔",
        "Security" => "🔒",
        "Appearance" => "🎨",
        _ => "⚙️"
    };
}

.settings-sidebar {
    min-width: 200px;
    background-color: var(--bs-light);
    border-radius: 0.5rem;
    padding: 0.5rem;
}

.settings-sidebar .nav-link {
    color: var(--bs-body-color);
    border-radius: 0.375rem;
    padding: 0.75rem 1rem;
    margin-bottom: 0.25rem;
    font-weight: 500;
    border: none;
    background: none;
    width: 100%;
}

.settings-sidebar .nav-link:hover:not(.active) {
    background-color: var(--bs-gray-200);
}

.settings-sidebar .nav-link.active {
    background-color: var(--bs-primary);
    color: white;
}

