@namespace sv_8222d9947e2f4a1e8633d4da37346d27.Components.Pages.Settings
@using sv_8222d9947e2f4a1e8633d4da37346d27.Services

<div class="card">
    <div class="card-header">
        <h5 class="mb-0">Profile Settings</h5>
    </div>
    <div class="card-body">
        @if (Profile is null)
        {
            <div class="text-center py-4">
                <div class="spinner-border" role="status">
                    <span class="visually-hidden">Loading...</span>
                </div>
            </div>
        }
        else
        {
            <div class="row">
                <div class="col-md-8">
                    <div class="mb-3">
                        <label for="displayName" class="form-label">Display Name</label>
                        <input type="text" class="form-control" id="displayName"
                               @bind="DisplayName" @bind:event="oninput" />
                    </div>

                    <div class="mb-3">
                        <label for="email" class="form-label">Email</label>
                        <input type="email" class="form-control" id="email"
                               @bind="Email" @bind:event="oninput" />
                    </div>

                    <div class="mb-3">
                        <label for="bio" class="form-label">Bio</label>
                        <textarea class="form-control" id="bio" rows="4"
                                  @bind="Bio" @bind:event="oninput"></textarea>
                    </div>
                </div>

                <div class="col-md-4">
                    <div class="text-center">
                        <label class="form-label d-block">Avatar Preview</label>
                        <div class="avatar-preview mb-2">
                            @if (!string.IsNullOrWhiteSpace(AvatarUrl))
                            {
                                <img src="@AvatarUrl" alt="Avatar" class="rounded-circle"
                                     style="width: 120px; height: 120px; object-fit: cover;"
                                     @onerror="HandleAvatarError" />
                            }
                            else
                            {
                                <div class="rounded-circle bg-secondary d-flex align-items-center justify-content-center text-white"
                                     style="width: 120px; height: 120px; font-size: 3rem; margin: 0 auto;">
                                    👤
                                </div>
                            }
                        </div>
                        <div class="mb-3">
                            <label for="avatarUrl" class="form-label">Avatar URL</label>
                            <input type="url" class="form-control form-control-sm" id="avatarUrl"
                                   @bind="AvatarUrl" @bind:event="oninput" />
                        </div>
                    </div>
                </div>
            </div>

            @if (!string.IsNullOrEmpty(_statusMessage))
            {
                <div class="alert @(_isSuccess ? "alert-success" : "alert-danger") alert-dismissible fade show mt-3" role="alert">
                    @_statusMessage
                    <button type="button" class="btn-close" @onclick="() => _statusMessage = null"></button>
                </div>
            }

            <div class="d-flex gap-2 mt-3">
                <button class="btn btn-primary" @onclick="SaveChanges" disabled="@_isSaving">
                    @if (_isSaving)
                    {
                        <span class="spinner-border spinner-border-sm me-1" role="status"></span>
                    }
                    Save Changes
                </button>
                <button class="btn btn-outline-secondary" @onclick="DiscardChanges" disabled="@_isSaving">
                    Discard Changes
                </button>
            </div>
        }
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public UserProfile? Profile { get; set; }

    [Parameter, EditorRequired]
    public EventCallback<UserProfile> OnSave { get; set; }

    private string DisplayName { get; set; } = "";
    private string Email { get; set; } = "";
    private string AvatarUrl { get; set; } = "";
    private string Bio { get; set; } = "";

    private bool _isSaving;
    private string? _statusMessage;
    private bool _isSuccess;
    private bool _avatarError;

    private UserProfile? _lastProfile;

    protected override void OnParametersSet()
    {
        if (Profile is not null && Profile != _lastProfile)
        {
            _lastProfile = Profile;
            LoadFromProfile(Profile);
        }
    }

    private void LoadFromProfile(UserProfile profile)
    {
        DisplayName = profile.DisplayName;
        Email = profile.Email;
        AvatarUrl = profile.AvatarUrl;
        Bio = profile.Bio;
        _avatarError = false;
    }

    private async Task SaveChanges()
    {
        _isSaving = true;
        _statusMessage = null;
        try
        {
            var updated = new UserProfile(DisplayName, Email, AvatarUrl, Bio);
            await OnSave.InvokeAsync(updated);
            _lastProfile = updated;
            _statusMessage = "Profile saved successfully!";
            _isSuccess = true;
        }
        catch (Exception ex)
        {
            _statusMessage = $"Error saving profile: {ex.Message}";
            _isSuccess = false;
        }
        finally
        {
            _isSaving = false;
        }
    }

    private void DiscardChanges()
    {
        if (_lastProfile is not null)
        {
            LoadFromProfile(_lastProfile);
        }
        _statusMessage = null;
    }

    private void HandleAvatarError()
    {
        _avatarError = true;
    }
}

@namespace sv_8222d9947e2f4a1e8633d4da37346d27.Components.Pages.Settings
@using sv_8222d9947e2f4a1e8633d4da37346d27.Services

<div class="card">
    <div class="card-header">
        <h5 class="mb-0">Notification Preferences</h5>
    </div>
    <div class="card-body">
        @if (Prefs is null)
        {
            <div class="text-center py-4">
                <div class="spinner-border" role="status">
                    <span class="visually-hidden">Loading...</span>
                </div>
            </div>
        }
        else
        {
            <div class="mb-4">
                <h6>General</h6>

                <div class="form-check form-switch mb-3">
                    <input class="form-check-input" type="checkbox" role="switch" id="emailNotif"
                           checked="@EmailNotifications" @onchange="e => EmailNotifications = (bool)e.Value!" />
                    <label class="form-check-label" for="emailNotif">
                        Email Notifications
                        <small class="d-block text-body-secondary">Receive notifications via email</small>
                    </label>
                </div>

                <div class="form-check form-switch mb-3">
                    <input class="form-check-input" type="checkbox" role="switch" id="pushNotif"
                           checked="@PushNotifications" @onchange="e => PushNotifications = (bool)e.Value!" />
                    <label class="form-check-label" for="pushNotif">
                        Push Notifications
                        <small class="d-block text-body-secondary">Receive push notifications in your browser</small>
                    </label>
                </div>

                <div class="form-check form-switch mb-3">
                    <input class="form-check-input" type="checkbox" role="switch" id="weeklyDigest"
                           checked="@WeeklyDigest" @onchange="e => WeeklyDigest = (bool)e.Value!" />
                    <label class="form-check-label" for="weeklyDigest">
                        Weekly Digest
                        <small class="d-block text-body-secondary">Get a weekly summary of activity</small>
                    </label>
                </div>
            </div>

            <div class="mb-4">
                <h6>Muted Channels</h6>
                <p class="text-body-secondary small">Select channels to mute notifications from.</p>

                @if (AvailableChannels.Count == 0)
                {
                    <p class="text-body-secondary fst-italic">No channels available.</p>
                }
                else
                {
                    <div class="list-group">
                        @foreach (var channel in AvailableChannels)
                        {
                            var isMuted = MutedChannels.Contains(channel);
                            <label class="list-group-item d-flex align-items-center gap-2">
                                <input class="form-check-input mt-0" type="checkbox"
                                       checked="@isMuted"
                                       @onchange="e => ToggleMute(channel, (bool)e.Value!)" />
                                <span>@channel</span>
                                @if (isMuted)
                                {
                                    <span class="badge bg-secondary ms-auto">Muted</span>
                                }
                            </label>
                        }
                    </div>
                }
            </div>

            @if (!string.IsNullOrEmpty(_statusMessage))
            {
                <div class="alert alert-success alert-dismissible fade show" role="alert">
                    @_statusMessage
                    <button type="button" class="btn-close" @onclick="() => _statusMessage = null"></button>
                </div>
            }

            <button class="btn btn-primary" @onclick="SavePreferences" disabled="@_isSaving">
                @if (_isSaving)
                {
                    <span class="spinner-border spinner-border-sm me-1" role="status"></span>
                }
                Save Preferences
            </button>
        }
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public NotificationPrefs? Prefs { get; set; }

    [Parameter]
    public List<string> AvailableChannels { get; set; } = ["general", "announcements", "engineering", "design", "marketing", "support"];

    [Parameter, EditorRequired]
    public EventCallback<NotificationPrefs> OnSave { get; set; }

    private bool EmailNotifications { get; set; }
    private bool PushNotifications { get; set; }
    private bool WeeklyDigest { get; set; }
    private List<string> MutedChannels { get; set; } = [];

    private bool _isSaving;
    private string? _statusMessage;
    private NotificationPrefs? _lastPrefs;

    protected override void OnParametersSet()
    {
        if (Prefs is not null && Prefs != _lastPrefs)
        {
            _lastPrefs = Prefs;
            EmailNotifications = Prefs.EmailNotifications;
            PushNotifications = Prefs.PushNotifications;
            WeeklyDigest = Prefs.WeeklyDigest;
            MutedChannels = [.. Prefs.MutedChannels];
        }
    }

    private void ToggleMute(string channel, bool muted)
    {
        if (muted && !MutedChannels.Contains(channel))
            MutedChannels.Add(channel);
        else if (!muted)
            MutedChannels.Remove(channel);
    }

    private async Task SavePreferences()
    {
        _isSaving = true;
        _statusMessage = null;
        try
        {
            var updated = new NotificationPrefs(EmailNotifications, PushNotifications, WeeklyDigest, [.. MutedChannels]);
            await OnSave.InvokeAsync(updated);
            _lastPrefs = updated;
            _statusMessage = "Notification preferences saved!";
        }
        catch (Exception ex)
        {
            _statusMessage = $"Error: {ex.Message}";
        }
        finally
        {
            _isSaving = false;
        }
    }
}

@namespace sv_8222d9947e2f4a1e8633d4da37346d27.Components.Pages.Settings
@using sv_8222d9947e2f4a1e8633d4da37346d27.Services

<div class="card">
    <div class="card-header">
        <h5 class="mb-0">Security Settings</h5>
    </div>
    <div class="card-body">
        @if (Settings is null)
        {
            <div class="text-center py-4">
                <div class="spinner-border" role="status">
                    <span class="visually-hidden">Loading...</span>
                </div>
            </div>
        }
        else
        {
            @* Change Password Panel *@
            <div class="mb-4">
                <div class="d-flex align-items-center justify-content-between mb-2">
                    <h6 class="mb-0">Change Password</h6>
                    <button class="btn btn-sm btn-outline-secondary" @onclick="TogglePasswordPanel">
                        @(_showPasswordPanel ? "Collapse" : "Expand")
                    </button>
                </div>

                @if (Settings.LastPasswordChange.HasValue)
                {
                    <small class="text-body-secondary">
                        Last changed: @Settings.LastPasswordChange.Value.ToString("MMMM dd, yyyy")
                    </small>
                }

                @if (_showPasswordPanel)
                {
                    <div class="border rounded p-3 mt-2">
                        <div class="mb-3">
                            <label for="currentPassword" class="form-label">Current Password</label>
                            <input type="password" class="form-control" id="currentPassword"
                                   @bind="_currentPassword" />
                        </div>
                        <div class="mb-3">
                            <label for="newPassword" class="form-label">New Password</label>
                            <input type="password" class="form-control" id="newPassword"
                                   @bind="_newPassword" />
                        </div>
                        <div class="mb-3">
                            <label for="confirmPassword" class="form-label">Confirm New Password</label>
                            <input type="password" class="form-control @(_passwordMismatch ? "is-invalid" : "")"
                                   id="confirmPassword" @bind="_confirmPassword" />
                            @if (_passwordMismatch)
                            {
                                <div class="invalid-feedback">Passwords do not match.</div>
                            }
                        </div>

                        @if (!string.IsNullOrEmpty(_passwordMessage))
                        {
                            <div class="alert @(_passwordSuccess ? "alert-success" : "alert-danger") py-2" role="alert">
                                @_passwordMessage
                            </div>
                        }

                        <button class="btn btn-warning" @onclick="UpdatePassword" disabled="@_isUpdatingPassword">
                            @if (_isUpdatingPassword)
                            {
                                <span class="spinner-border spinner-border-sm me-1" role="status"></span>
                            }
                            Update Password
                        </button>
                    </div>
                }
            </div>

            <hr />

            @* Two-Factor Authentication *@
            <div class="mb-4">
                <h6>Two-Factor Authentication</h6>
                <div class="d-flex align-items-center gap-3">
                    <div class="form-check form-switch">
                        <input class="form-check-input" type="checkbox" role="switch" id="twoFactor"
                               checked="@Settings.TwoFactorEnabled" disabled />
                        <label class="form-check-label" for="twoFactor">
                            Two-factor authentication
                        </label>
                    </div>
                    <span class="badge @(Settings.TwoFactorEnabled ? "bg-success" : "bg-warning text-dark")">
                        @(Settings.TwoFactorEnabled ? "Enabled" : "Disabled")
                    </span>
                </div>
            </div>

            <hr />

            @* Active Sessions *@
            <div>
                <h6>Active Sessions</h6>
                @if (Settings.Sessions.Count == 0)
                {
                    <p class="text-body-secondary">No active sessions.</p>
                }
                else
                {
                    <div class="table-responsive">
                        <table class="table table-hover align-middle">
                            <thead>
                                <tr>
                                    <th>Device</th>
                                    <th>Location</th>
                                    <th>Last Active</th>
                                    <th class="text-end">Action</th>
                                </tr>
                            </thead>
                            <tbody>
                                @foreach (var session in Settings.Sessions)
                                {
                                    var isCurrent = session == Settings.Sessions.FirstOrDefault();
                                    <tr>
                                        <td>
                                            @session.Device
                                            @if (isCurrent)
                                            {
                                                <span class="badge bg-info ms-1">Current</span>
                                            }
                                        </td>
                                        <td>@session.Location</td>
                                        <td>@FormatLastActive(session.LastActive)</td>
                                        <td class="text-end">
                                            @if (!isCurrent)
                                            {
                                                <button class="btn btn-sm btn-outline-danger"
                                                        @onclick="() => PromptRevoke(session)">
                                                    Revoke
                                                </button>
                                            }
                                        </td>
                                    </tr>
                                }
                            </tbody>
                        </table>
                    </div>
                }
            </div>

            @* Revoke Confirmation Dialog *@
            @if (_sessionToRevoke is not null)
            {
                <div class="modal-backdrop fade show"></div>
                <div class="modal fade show d-block" tabindex="-1" role="dialog">
                    <div class="modal-dialog modal-dialog-centered" role="document">
                        <div class="modal-content">
                            <div class="modal-header">
                                <h5 class="modal-title">Revoke Session</h5>
                                <button type="button" class="btn-close" @onclick="CancelRevoke"></button>
                            </div>
                            <div class="modal-body">
                                <p>Are you sure you want to revoke the session on <strong>@_sessionToRevoke.Device</strong> from <strong>@_sessionToRevoke.Location</strong>?</p>
                                <p class="text-body-secondary small">This will sign out the device immediately.</p>
                            </div>
                            <div class="modal-footer">
                                <button type="button" class="btn btn-secondary" @onclick="CancelRevoke">Cancel</button>
                                <button type="button" class="btn btn-danger" @onclick="ConfirmRevoke" disabled="@_isRevoking">
                                    @if (_isRevoking)
                                    {
                                        <span class="spinner-border spinner-border-sm me-1" role="status"></span>
                                    }
                                    Revoke Session
                                </button>
                            </div>
                        </div>
                    </div>
                </div>
            }
        }
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public SecuritySettings? Settings { get; set; }

    [Parameter, EditorRequired]
    public EventCallback<string> OnChangePassword { get; set; }

    [Parameter, EditorRequired]
    public EventCallback<string> OnRevokeSession { get; set; }

    private bool _showPasswordPanel;
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private bool _isUpdatingPassword;
    private string? _passwordMessage;
    private bool _passwordSuccess;
    private bool _passwordMismatch;

    private ActiveSession? _sessionToRevoke;
    private bool _isRevoking;

    private void TogglePasswordPanel() => _showPasswordPanel = !_showPasswordPanel;

    private async Task UpdatePassword()
    {
        _passwordMismatch = _newPassword != _confirmPassword;
        if (_passwordMismatch) return;

        if (string.IsNullOrWhiteSpace(_currentPassword) || string.IsNullOrWhiteSpace(_newPassword))
        {
            _passwordMessage = "Please fill in all password fields.";
            _passwordSuccess = false;
            return;
        }

        _isUpdatingPassword = true;
        _passwordMessage = null;
        try
        {
            // Pass "currentPassword|newPassword" via the callback
            await OnChangePassword.InvokeAsync($"{_currentPassword}|{_newPassword}");
            _passwordMessage = "Password updated successfully!";
            _passwordSuccess = true;
            _currentPassword = "";
            _newPassword = "";
            _confirmPassword = "";
        }
        catch (Exception ex)
        {
            _passwordMessage = $"Error: {ex.Message}";
            _passwordSuccess = false;
        }
        finally
        {
            _isUpdatingPassword = false;
        }
    }

    private void PromptRevoke(ActiveSession session) => _sessionToRevoke = session;

    private void CancelRevoke() => _sessionToRevoke = null;

    private async Task ConfirmRevoke()
    {
        if (_sessionToRevoke is null) return;

        _isRevoking = true;
        try
        {
            await OnRevokeSession.InvokeAsync(_sessionToRevoke.Id);
            _sessionToRevoke = null;
        }
        catch
        {
            // keep dialog open on failure
        }
        finally
        {
            _isRevoking = false;
        }
    }

    private static string FormatLastActive(DateTime lastActive)
    {
        var ago = DateTime.UtcNow - lastActive;
        if (ago.TotalMinutes < 1) return "Just now";
        if (ago.TotalHours < 1) return $"{(int)ago.TotalMinutes}m ago";
        if (ago.TotalDays < 1) return $"{(int)ago.TotalHours}h ago";
        return lastActive.ToString("MMM dd, yyyy HH:mm");
    }
}

@namespace sv_8222d9947e2f4a1e8633d4da37346d27.Components.Pages.Settings
@using sv_8222d9947e2f4a1e8633d4da37346d27.Services

<div class="card">
    <div class="card-header">
        <h5 class="mb-0">Appearance Settings</h5>
    </div>
    <div class="card-body">
        @if (Settings is null)
        {
            <div class="text-center py-4">
                <div class="spinner-border" role="status">
                    <span class="visually-hidden">Loading...</span>
                </div>
            </div>
        }
        else
        {
            <div class="row">
                <div class="col-md-7">
                    @* Theme *@
                    <div class="mb-4">
                        <h6>Theme</h6>
                        <div class="btn-group" role="group">
                            @foreach (var theme in new[] { "Light", "Dark", "System" })
                            {
                                <input type="radio" class="btn-check" name="theme" id="theme-@theme"
                                       checked="@(Theme == theme)"
                                       @onchange="() => Theme = theme" />
                                <label class="btn btn-outline-primary" for="theme-@theme">
                                    @GetThemeIcon(theme) @theme
                                </label>
                            }
                        </div>
                    </div>

                    @* Font Size *@
                    <div class="mb-4">
                        <h6>Font Size</h6>
                        <div class="btn-group" role="group">
                            @foreach (var size in new[] { "Small", "Medium", "Large" })
                            {
                                <input type="radio" class="btn-check" name="fontSize" id="font-@size"
                                       checked="@(FontSize == size)"
                                       @onchange="() => FontSize = size" />
                                <label class="btn btn-outline-secondary" for="font-@size">@size</label>
                            }
                        </div>
                    </div>

