@code {
    [Parameter, EditorRequired]
    public SecuritySettings? Settings { get; set; }

    [Parameter, EditorRequired]
    public EventCallback<string> OnChangePassword { get; set; }

    [Parameter, EditorRequired]
    public EventCallback<string> OnRevokeSession { get; set; }

    private bool _showPasswordPanel;
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private bool _isUpdatingPassword;
    private string? _passwordMessage;
    private bool _passwordSuccess;
    private bool _passwordMismatch;

    private ActiveSession? _sessionToRevoke;
    private bool _isRevoking;

    private void TogglePasswordPanel() => _showPasswordPanel = !_showPasswordPanel;

    private async Task UpdatePassword()
    {
        _passwordMismatch = _newPassword != _confirmPassword;
        if (_passwordMismatch) return;

        if (string.IsNullOrWhiteSpace(_currentPassword) || string.IsNullOrWhiteSpace(_newPassword))
        {
            _passwordMessage = "Please fill in all password fields.";
            _passwordSuccess = false;
            return;
        }

        _isUpdatingPassword = true;
        _passwordMessage = null;
        try
        {
            // Pass "currentPassword|newPassword" via the callback
            await OnChangePassword.InvokeAsync($"{_currentPassword}|{_newPassword}");
            _passwordMessage = "Password updated successfully!";
            _passwordSuccess = true;
            _currentPassword = "";
            _newPassword = "";
            _confirmPassword = "";
        }
        catch (Exception ex)
        {
            _passwordMessage = $"Error: {ex.Message}";
            _passwordSuccess = false;
        }
        finally
        {
            _isUpdatingPassword = false;
        }
    }

    private void PromptRevoke(ActiveSession session) => _sessionToRevoke = session;

    private void CancelRevoke() => _sessionToRevoke = null;

    private async Task ConfirmRevoke()
    {
        if (_sessionToRevoke is null) return;

        _isRevoking = true;
        try
        {
            await OnRevokeSession.InvokeAsync(_sessionToRevoke.Id);
            _sessionToRevoke = null;
        }
        catch
        {
            // keep dialog open on failure
        }
        finally
        {
            _isRevoking = false;
        }
    }

    private static string FormatLastActive(DateTime lastActive)
    {
        var ago = DateTime.UtcNow - lastActive;
        if (ago.TotalMinutes < 1) return "Just now";
        if (ago.TotalHours < 1) return $"{(int)ago.TotalMinutes}m ago";
        if (ago.TotalDays < 1) return $"{(int)ago.TotalHours}h ago";
        return lastActive.ToString("MMM dd, yyyy HH:mm");
    }
}

