@namespace sv_8222d9947e2f4a1e8633d4da37346d27.Components.Pages.Settings
@using sv_8222d9947e2f4a1e8633d4da37346d27.Services

<div class="card">
    <div class="card-header">
        <h5 class="mb-0">Appearance Settings</h5>
    </div>
    <div class="card-body">
        @if (Settings is null)
        {
            <div class="text-center py-4">
                <div class="spinner-border" role="status">
                    <span class="visually-hidden">Loading...</span>
                </div>
            </div>
        }
        else
        {
            <div class="row">
                <div class="col-md-7">
                    @* Theme *@
                    <div class="mb-4">
                        <h6>Theme</h6>
                        <div class="btn-group" role="group">
                            @foreach (var theme in new[] { "Light", "Dark", "System" })
                            {
                                <input type="radio" class="btn-check" name="theme" id="theme-@theme"
                                       checked="@(Theme == theme)"
                                       @onchange="() => Theme = theme" />
                                <label class="btn btn-outline-primary" for="theme-@theme">
                                    @GetThemeIcon(theme) @theme
                                </label>
                            }
                        </div>
                    </div>

                    @* Font Size *@
                    <div class="mb-4">
                        <h6>Font Size</h6>
                        <div class="btn-group" role="group">
                            @foreach (var size in new[] { "Small", "Medium", "Large" })
                            {
                                <input type="radio" class="btn-check" name="fontSize" id="font-@size"
                                       checked="@(FontSize == size)"
                                       @onchange="() => FontSize = size" />
                                <label class="btn btn-outline-secondary" for="font-@size">@size</label>
                            }
                        </div>
                    </div>

                    @* Language *@
                    <div class="mb-4">
                        <h6>Language</h6>
                        <select class="form-select" style="max-width: 300px;"
                                @bind="Language">
                            <option value="en">English</option>
                            <option value="es">Español</option>
                            <option value="fr">Français</option>
                            <option value="de">Deutsch</option>
                            <option value="ja">日本語</option>
                            <option value="zh">中文</option>
                            <option value="pt">Português</option>
                        </select>
                    </div>

                    @* Compact Mode *@
                    <div class="mb-4">
                        <div class="form-check form-switch">
                            <input class="form-check-input" type="checkbox" role="switch" id="compactMode"
                                   checked="@CompactMode" @onchange="e => CompactMode = (bool)e.Value!" />
                            <label class="form-check-label" for="compactMode">
                                Compact Mode
                                <small class="d-block text-body-secondary">Reduce spacing and padding throughout the UI</small>
                            </label>
                        </div>
                    </div>
                </div>

                @* Live Preview *@
                <div class="col-md-5">
                    <h6>Preview</h6>
                    <div class="border rounded p-3 @GetPreviewClasses()" style="@GetPreviewStyles()">
                        <div class="@(CompactMode ? "mb-1" : "mb-3")">
                            <strong>Sample Heading</strong>
                        </div>
                        <p class="@(CompactMode ? "mb-1" : "mb-2")">
                            This is a preview of how your content will look with the selected appearance settings.
                        </p>
                        <div class="d-flex gap-2 @(CompactMode ? "mb-1" : "mb-2")">
                            <span class="badge bg-primary">Tag</span>
                            <span class="badge bg-success">Active</span>
                            <span class="badge bg-warning text-dark">Pending</span>
                        </div>
                        <button class="btn btn-sm btn-primary @(CompactMode ? "btn-sm py-0" : "")">
                            Sample Button
                        </button>
                    </div>
                </div>
            </div>

            @if (!string.IsNullOrEmpty(_statusMessage))
            {
                <div class="alert alert-success alert-dismissible fade show mt-3" role="alert">
                    @_statusMessage
                    <button type="button" class="btn-close" @onclick="() => _statusMessage = null"></button>
                </div>
            }

            <button class="btn btn-primary mt-3" @onclick="Save" disabled="@_isSaving">
                @if (_isSaving)
                {
                    <span class="spinner-border spinner-border-sm me-1" role="status"></span>
                }
                Save
            </button>
        }
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public AppearanceSettings? Settings { get; set; }

    [Parameter, EditorRequired]
    public EventCallback<AppearanceSettings> OnSave { get; set; }

    private string Theme { get; set; } = "System";
    private string FontSize { get; set; } = "Medium";
    private string Language { get; set; } = "en";
    private bool CompactMode { get; set; }

    private bool _isSaving;
    private string? _statusMessage;
    private AppearanceSettings? _lastSettings;

    protected override void OnParametersSet()
    {
        if (Settings is not null && Settings != _lastSettings)
        {
            _lastSettings = Settings;
            Theme = Settings.Theme;
            FontSize = Settings.FontSize;
            Language = Settings.Language;
            CompactMode = Settings.CompactMode;
        }
    }

    private async Task Save()
    {
        _isSaving = true;
        _statusMessage = null;
        try
        {
            var updated = new AppearanceSettings(Theme, FontSize, Language, CompactMode);
            await OnSave.InvokeAsync(updated);
            _lastSettings = updated;
            _statusMessage = "Appearance settings saved!";
        }
        catch (Exception ex)
        {
            _statusMessage = $"Error: {ex.Message}";
        }
        finally
        {
            _isSaving = false;
        }
    }

    private string GetPreviewClasses()
    {
        return Theme switch
        {
            "Dark" => "bg-dark text-light",
            "Light" => "bg-white text-dark",
            _ => "bg-body text-body"
        };
    }

    private string GetPreviewStyles()
    {
        var fontSize = FontSize switch
        {
            "Small" => "0.85rem",
            "Large" => "1.15rem",
            _ => "1rem"
        };
        var padding = CompactMode ? "0.5rem" : "1rem";
        return $"font-size: {fontSize}; padding: {padding}; transition: all 0.2s ease;";
    }

    private static string GetThemeIcon(string theme) => theme switch
    {
        "Light" => "☀️",
        "Dark" => "🌙",
        "System" => "💻",
        _ => ""
    };
}

